th:32px;height:32px;border-radius:50%;background:var(--accent,#007aff);color:white;display:flex;align-items:center;justify-content:center}.date-num[data-v-12af839d]{display:flex;align-items:center;justify-content:center;width:32px;height:32px;font-variant-numeric:tabular-nums}.event-dot[data-v-12af839d]{width:5px;height:5px;border-radius:50%;background:var(--accent,#007aff);position:absolute;bottom:4px}.date-cell.today .event-dot[data-v-12af839d]{background:white}.events-section[data-v-12af839d]{flex:1;overflow-y:auto;padding:12px 16px;border-top:0.5px solid var(--border-secondary);margin-top:4px}.events-header[data-v-12af839d]{margin-bottom:10px}.events-date[data-v-12af839d]{font-size:17px;font-weight:700;color:var(--text-primary)}.event-form[data-v-12af839d]{display:grid;grid-template-columns:1fr 90px auto;gap:6px;margin-bottom:10px}.event-form input[data-v-12af839d]{min-width:0;border:none;border-radius:9px;padding:8px 9px;background:var(--bg-secondary);color:var(--text-primary);outline:none}.event-form button[data-v-12af839d],.delete-event[data-v-12af839d]{border:none;border-radius:9px;padding:7px 9px;background:var(--accent,#007aff);color:white;font-size:12px;cursor:pointer}.event-list[data-v-12af839d]{display:flex;flex-direction:column;gap:8px}.event-item[data-v-12af839d]{display:flex;align-items:stretch;gap:10px;padding:10px 12px;background:var(--bg-secondary);border-radius:10px}.event-color-bar[data-v-12af839d]{width:4px;border-radius:2px;flex-shrink:0}.event-info[data-v-12af839d]{flex:1;display:flex;flex-direction:column;gap:2px}.event-title[data-v-12af839d]{font-size:14px;font-weight:500;color:var(--text-primary)}.event-time[data-v-12af839d]{font-size:12px;color:var(--text-tertiary)}.delete-event[data-v-12af839d]{background:var(--bg-tertiary);color:var(--text-tertiary);align-self:center}.no-events[data-v-12af839d]{text-align:center;padding:20px;font-size:14px;color:var(--text-tertiary)}
